const CONFIG = {
  // 1) Dirección base de la API de la página web, sin / al final.
  apiBaseUrl: 'https://asesoriainmobiliariajb.com',
  endpointConciliar: '/api/n8n/arrendamientos/conciliar-pago',
  endpointRegistrar: '/api/n8n/arrendamientos/registrar-pago',

  // 2) Correo interno que recibe casos no conciliados o con errores.
  correoInterno: 'pagos@REEMPLAZAR-DOMINIO.com',

  // 3) Copie aquí la dirección EXACTA del remitente de una notificación
  // auténtica de Bancolombia previamente verificada.
  remitentesExactosPermitidos: [
    'REEMPLAZAR-CON-REMITENTE-REAL@bancolombia.com.co',
  ],
  dominiosPermitidos: ['bancolombia.com.co'],
  requiereRemitenteExacto: true,

  // 4) Últimos 4 dígitos de las cuentas que reciben los cánones.
  cuentasReceptorasUltimos4: ['0000'],

  // Diferencia máxima aceptable frente al valor esperado del contrato.
  toleranciaValorCOP: 0,
  moneda: 'COP',
};

const raw = $input.first().json ?? {};

const pick = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
};

const normalize = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const decodeEntities = (value) =>
  String(value ?? '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');

const htmlToText = (value) =>
  decodeEntities(value)
    .replace(/<(br|\/p|\/div|\/tr|\/li|\/h[1-6])\b[^>]*>/gi, '\n')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const bodyRaw = pick(
  raw.body?.content,
  raw.bodyContent,
  raw.html,
  raw.text,
  raw.bodyPreview,
  raw.snippet,
);

const texto = htmlToText(bodyRaw);
const asunto = String(pick(raw.subject, raw.asunto)).trim();
const remitente = normalize(
  pick(
    raw.from?.emailAddress?.address,
    raw.sender?.emailAddress?.address,
    raw.from?.address,
    raw.sender?.address,
    raw.from,
    raw.sender,
  ),
);

const remitenteNombre = String(
  pick(
    raw.from?.emailAddress?.name,
    raw.sender?.emailAddress?.name,
    raw.from?.name,
    raw.sender?.name,
  ),
).trim();

const correoId = String(
  pick(raw.id, raw.messageId, raw.internetMessageId, raw.internet_message_id),
).trim();

const recibidoEn = String(
  pick(raw.receivedDateTime, raw.date, raw.createdDateTime, new Date().toISOString()),
).trim();

const remitentesConfigurados = CONFIG.remitentesExactosPermitidos
  .map(normalize)
  .filter((value) => value && !value.startsWith('reemplazar-'));

const cuentasConfiguradas = CONFIG.cuentasReceptorasUltimos4
  .map((value) => String(value).replace(/\D/g, '').slice(-4))
  .filter((value) => value.length === 4 && value !== '0000');

const dominio = remitente.includes('@') ? remitente.split('@').pop() : '';
const coincideDominio = CONFIG.dominiosPermitidos.some(
  (permitido) =>
    dominio === normalize(permitido) ||
    dominio.endsWith(`.${normalize(permitido)}`),
);
const coincideRemitenteExacto = remitentesConfigurados.includes(remitente);

const remitentePermitido = CONFIG.requiereRemitenteExacto
  ? coincideRemitenteExacto && coincideDominio
  : coincideRemitenteExacto || coincideDominio;

const textoCompleto = `${asunto}\n${texto}`;
const textoNormalizado = normalize(textoCompleto);

const contieneMarca = textoNormalizado.includes('bancolombia');
const contieneOperacion = [
  'pago',
  'transferencia',
  'abono',
  'consignacion',
  'deposito',
  'recibiste',
  'transaccion',
].some((word) => textoNormalizado.includes(word));

const parseMoney = (candidate) => {
  let value = String(candidate ?? '')
    .replace(/\s/g, '')
    .replace(/[^\d.,-]/g, '');

  if (!value || !/\d/.test(value)) return null;

  const lastDot = value.lastIndexOf('.');
  const lastComma = value.lastIndexOf(',');

  if (lastDot >= 0 && lastComma >= 0) {
    const decimalSeparator = lastDot > lastComma ? '.' : ',';
    const thousandsSeparator = decimalSeparator === '.' ? ',' : '.';
    value = value.split(thousandsSeparator).join('');
    value = value.replace(decimalSeparator, '.');
  } else if (lastComma >= 0) {
    const decimals = value.length - lastComma - 1;
    value =
      decimals === 1 || decimals === 2
        ? value.replace(/\./g, '').replace(',', '.')
        : value.replace(/,/g, '');
  } else if (lastDot >= 0) {
    const dotCount = (value.match(/\./g) || []).length;
    const decimals = value.length - lastDot - 1;
    value =
      dotCount > 1 || decimals === 3
        ? value.replace(/\./g, '')
        : value;
  }

  const amount = Number(value);
  return Number.isFinite(amount) && amount > 0 ? amount : null;
};

const amountPatterns = [
  /(?:valor|monto|abono|pago|transferencia|consignaci[oó]n|recibiste)\s*(?:de|por|:|-)?\s*(?:cop|col\$|\$)?\s*([\d][\d.,\s]{2,24})/gi,
  /(?:cop|col\$|\$)\s*([\d][\d.,\s]{2,24})/gi,
];

let valor = null;
for (const pattern of amountPatterns) {
  for (const match of textoCompleto.matchAll(pattern)) {
    const parsed = parseMoney(match[1]);
    if (parsed && parsed < 1_000_000_000_000) {
      valor = parsed;
      break;
    }
  }
  if (valor) break;
}

const accountPatterns = [
  /(?:cuenta|producto)\s*(?:destino|receptora|beneficiaria|abonada|a la que llega|n[uú]mero|no\.?)?\s*(?:es|:|-)?\s*([xX*#\d][xX*#\d\s-]{3,30})/gi,
  /(?:terminada|finalizada|finaliza|termina)\s+en\s+(\d{4})/gi,
];

const cuentasDetectadas = [];
for (const pattern of accountPatterns) {
  for (const match of textoCompleto.matchAll(pattern)) {
    const digits = String(match[1]).replace(/\D/g, '');
    if (digits.length >= 4) {
      const account = {
        valorDetectado: String(match[1]).trim(),
        digitos: digits,
        ultimos4: digits.slice(-4),
      };
      if (
        !cuentasDetectadas.some(
          (existing) =>
            existing.digitos === account.digitos &&
            existing.ultimos4 === account.ultimos4,
        )
      ) {
        cuentasDetectadas.push(account);
      }
    }
  }
}

const cuentaAutorizada = cuentasDetectadas.find((account) =>
  cuentasConfiguradas.includes(account.ultimos4),
);

const lines = texto
  .split(/\n+/)
  .map((line) => line.trim())
  .filter(Boolean);

const cleanExtractedText = (value) =>
  String(value ?? '')
    .replace(/^[\s:–—-]+/, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/[|]+.*$/, '')
    .trim();

const extractLineValue = (labels, maxLength = 120) => {
  for (const line of lines) {
    const normalizedLine = normalize(line);
    for (const label of labels) {
      const normalizedLabel = normalize(label);
      const index = normalizedLine.indexOf(normalizedLabel);
      if (index >= 0) {
        let value = line.slice(index + label.length);
        value = cleanExtractedText(value);
        if (value && value.length <= maxLength) return value;
      }
    }
  }
  return '';
};

let pagador = extractLineValue([
  'nombre del pagador',
  'nombre de quien paga',
  'pagador',
  'ordenante',
  'enviado por',
  'transferido por',
  'de:',
]);

if (!pagador) {
  const match = textoCompleto.match(
    /(?:pagador|ordenante|enviado por|transferido por)\s*(?:es|:|-)?\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑa-záéíóúñ .'-]{3,100})/i,
  );
  pagador = cleanExtractedText(match?.[1] ?? '');
}

let referencia = extractLineValue([
  'número de transacción',
  'numero de transaccion',
  'referencia bancaria',
  'referencia',
  'comprobante',
  'código de operación',
  'codigo de operacion',
  'id de transacción',
  'id de transaccion',
], 80);

if (!referencia) {
  const match = textoCompleto.match(
    /(?:referencia|comprobante|transacci[oó]n|operaci[oó]n)\s*(?:n[uú]mero|no\.?|id|:|-)?\s*([A-Z0-9-]{5,50})/i,
  );
  referencia = cleanExtractedText(match?.[1] ?? '');
}

let fechaPago = extractLineValue([
  'fecha y hora',
  'fecha del pago',
  'fecha de la transacción',
  'fecha de la transaccion',
  'fecha:',
], 60);

const advertencias = [];

if (!remitentesConfigurados.length) {
  advertencias.push(
    'No se ha configurado un remitente exacto autorizado de Bancolombia.',
  );
}
if (!cuentasConfiguradas.length) {
  advertencias.push(
    'No se han configurado los últimos 4 dígitos de las cuentas receptoras.',
  );
}
if (!valor) advertencias.push('No fue posible extraer el valor del pago.');
if (!pagador) advertencias.push('No fue posible extraer el nombre del pagador.');
if (!cuentaAutorizada) {
  advertencias.push(
    'No se detectó una cuenta receptora incluida en la lista autorizada.',
  );
}
if (!referencia) {
  advertencias.push(
    'No se detectó referencia bancaria; se usará el ID del correo para evitar duplicados.',
  );
}

const esBancolombia =
  remitentePermitido && contieneMarca && contieneOperacion;

const datosMinimos =
  Boolean(valor) &&
  Boolean(pagador) &&
  Boolean(cuentaAutorizada) &&
  Boolean(correoId);

const referenciaIdempotencia = referencia || correoId;

return [
  {
    json: {
      config: CONFIG,
      correo: {
        id: correoId,
        asunto,
        remitente,
        remitenteNombre,
        recibidoEn,
        bodyPreview: texto.slice(0, 2000),
      },
      pago: {
        banco: 'Bancolombia',
        moneda: CONFIG.moneda,
        valor,
        pagador,
        cuentaDestino: cuentaAutorizada?.valorDetectado || '',
        ultimos4Cuenta: cuentaAutorizada?.ultimos4 || '',
        cuentasDetectadas,
        referencia,
        referenciaIdempotencia,
        fechaPago: fechaPago || recibidoEn,
      },
      validacion: {
        esBancolombia,
        datosMinimos,
        remitentePermitido,
        coincideRemitenteExacto,
        coincideDominio,
        contieneMarca,
        contieneOperacion,
        advertencias,
      },
    },
  },
];

const source = $('Extraer y validar notificación').item.json;
const http = $json ?? {};

const statusCode = Number(http.statusCode ?? 200);
const body = http.body ?? http;

const responseData =
  body?.data && typeof body.data === 'object' ? body.data : body;

const arrendatario =
  responseData?.arrendatario ??
  responseData?.tenant ??
  responseData?.cliente ??
  {};

const apiCoincide = Boolean(
  responseData?.coincide ??
    responseData?.match ??
    responseData?.matched ??
    false,
);

const email = String(
  arrendatario.email ??
    arrendatario.correo ??
    arrendatario.emailArrendatario ??
    '',
).trim();

const valorEsperadoRaw =
  arrendatario.valorEsperado ??
  arrendatario.canon ??
  arrendatario.valorCanon ??
  responseData.valorEsperado ??
  null;

const valorEsperado =
  valorEsperadoRaw === null || valorEsperadoRaw === undefined
    ? null
    : Number(valorEsperadoRaw);

const diferenciaValor =
  valorEsperado !== null && Number.isFinite(valorEsperado)
    ? Math.abs(Number(source.pago.valor) - valorEsperado)
    : null;

const valorAceptable =
  diferenciaValor === null ||
  diferenciaValor <= Number(source.config.toleranciaValorCOP ?? 0);

const respuestaHTTPValida = statusCode >= 200 && statusCode < 300;

const coincide =
  respuestaHTTPValida &&
  apiCoincide &&
  Boolean(email) &&
  valorAceptable;

const motivos = [];

if (!respuestaHTTPValida) {
  motivos.push(`La API respondió con estado HTTP ${statusCode}.`);
}
if (!apiCoincide) {
  motivos.push(
    String(
      responseData?.motivo ??
        responseData?.reason ??
        'La base de datos no encontró una coincidencia.',
    ),
  );
}
if (!email) {
  motivos.push('El registro coincidente no tiene correo electrónico.');
}
if (!valorAceptable) {
  motivos.push(
    `La diferencia entre el pago y el valor esperado es de ${diferenciaValor} COP.`,
  );
}

return [
  {
    json: {
      ...source,
      conciliacion: {
        coincide,
        motivos,
        statusCode,
        valorEsperado,
        diferenciaValor,
        arrendatario: {
          id:
            arrendatario.id ??
            arrendatario.arrendatarioId ??
            arrendatario.clienteId ??
            '',
          nombre:
            arrendatario.nombre ??
            arrendatario.nombreCompleto ??
            arrendatario.razonSocial ??
            '',
          email,
          contratoId:
            arrendatario.contratoId ??
            arrendatario.idContrato ??
            '',
          contrato:
            arrendatario.contrato ??
            arrendatario.numeroContrato ??
            '',
          inmueble:
            arrendatario.inmueble ??
            arrendatario.direccionInmueble ??
            arrendatario.predio ??
            '',
          valorEsperado,
        },
        respuestaApi: responseData,
      },
    },
  },
];

const source = $('Evaluar conciliación').item.json;
const http = $json ?? {};
const statusCode = Number(http.statusCode ?? 200);
const body = http.body ?? http;
const data = body?.data && typeof body.data === 'object' ? body.data : body;

const duplicado = Boolean(
  data?.duplicado ??
    data?.duplicate ??
    data?.alreadyExists ??
    statusCode === 409,
);

const registrado = Boolean(
  data?.registrado ??
    data?.created ??
    data?.success ??
    (statusCode >= 200 && statusCode < 300),
);

const ok = registrado || duplicado;

const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const amount = Number(source.pago.valor ?? 0).toLocaleString('es-CO', {
  style: 'currency',
  currency: 'COP',
  maximumFractionDigits: 0,
});

const arr = source.conciliacion.arrendatario;
const fecha = new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota',
  dateStyle: 'long',
  timeStyle: 'short',
}).format(new Date());

const html = `
<!doctype html>
<html lang="es">
  <body style="font-family:Arial,sans-serif;line-height:1.55;color:#222">
    <h2>Confirmación de pago recibido</h2>
    <p>Hola, <strong>${esc(arr.nombre || 'arrendatario')}</strong>.</p>
    <p>Hemos identificado y registrado el siguiente pago:</p>
    <table cellpadding="6" cellspacing="0" style="border-collapse:collapse">
      <tr><td><strong>Valor</strong></td><td>${esc(amount)}</td></tr>
      <tr><td><strong>Pagador</strong></td><td>${esc(source.pago.pagador)}</td></tr>
      <tr><td><strong>Cuenta receptora</strong></td><td>Terminada en ${esc(source.pago.ultimos4Cuenta)}</td></tr>
      <tr><td><strong>Referencia</strong></td><td>${esc(source.pago.referenciaIdempotencia)}</td></tr>
      <tr><td><strong>Contrato</strong></td><td>${esc(arr.contrato || arr.contratoId)}</td></tr>
      <tr><td><strong>Inmueble</strong></td><td>${esc(arr.inmueble)}</td></tr>
      <tr><td><strong>Registro</strong></td><td>${esc(fecha)}</td></tr>
    </table>
    <p>Conserva el comprobante bancario. Esta confirmación corresponde a la conciliación automática de la notificación recibida y podrá ser revisada si el banco reporta una reversión o inconsistencia.</p>
    <p>Cordialmente,<br><strong>BUIJO — Administración de arrendamientos</strong></p>
  </body>
</html>`;

return [
  {
    json: {
      ...source,
      registro: {
        ok,
        registrado,
        duplicado,
        statusCode,
        pagoId: data?.pagoId ?? data?.id ?? '',
        respuestaApi: data,
      },
      confirmacion: {
        destinatario: arr.email,
        asunto: `Confirmación de pago - ${source.pago.referenciaIdempotencia}`,
        html,
      },
    },
  },
];
